mapper.select:
SELECT A.FINPROD_ID finprodId, A.FINPROD_MARKET_ID finprodMarketId, A.FINPROD_NAME finprodName, A.FINPROD_TYPE2, A.CCY ccy, A.VDATE vdate, A.MDATE mdate, T.CUSTOMER_NAME manager, A.CALENDAR_ID calendarId, A.CAPI_INCOME_FEATURE capiIncomeFeature,
A.CONTRACT_NO contractNo,
T1.CUSTOMER_NAME trusteeId, T2.CUSTOMER_NAME issuer,
A.ISSUE_AMT issueAmt, B.TYPE_6 category, B.TYPE_7 type,
B.TYPE_9 type9, B.TYPE_10 type10, B.TYPE_11 type11, B.TYPE_12 type12,
/*(CASE WHEN C.PUR_SPEED = 0 THEN 'T+0' WHEN C.PUR_SPEED = 1 THEN 'T+1' ELSE 'T+2' END) transMode,*/ (CASE WHEN C.PUR_SPEED is not null THEN 'T+'||C.PUR_SPEED ELSE '' END) purSpeed, (CASE WHEN C.RED_SPEED is not null THEN 'T+'||C.RED_SPEED ELSE '' END) redSpeed,
D.CASH_OUT_NO cmsId, D.INVESTMENT_ATTRIBUTES investmentAttributes,
D.TRIAL_NO trialNo,
FPR.recommender recommender, FPR.recommenderName recommenderName,
T3.CUSTOMER_NAME actualManager
FROM FIN_PRODUCT A inner join FIN_PRODUCT_TYPE B on A.FINPROD_ID = B.FINPROD_ID inner join FIN_PRODUCT_ADD C on A.FINPROD_ID = C.FINPROD_ID inner join PA_FIN_PRODUCT D on A.FINPROD_ID = D.FINPROD_ID AND B.FINPROD_ID = D.FINPROD_ID
LEFT JOIN ( SELECT FPR.FINPROD_ID, listagg(FPR.RECOMMENDER,'，') within group(order by FPR.RECOMMENDER) recommender, listagg(MCP.COUNTER_NAME,'，') within group(order by FPR.RECOMMENDER) recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = A.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO T ON T.CUSTOMER_ID = A.MANAGER
LEFT JOIN MST_CUSTOMER_INFO T1 ON T1.CUSTOMER_ID = A.TRUSTEE_ID LEFT JOIN MST_CUSTOMER_INFO T2 ON T2.CUSTOMER_ID = A.ISSUER LEFT JOIN MST_CUSTOMER_INFO T3 ON T3.CUSTOMER_ID = D.ACTUAL_MANAGER
WHERE 1=1
AND A.FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{finprodMarketId}),'%')
#{category,jdbcType=VARCHAR}
#{type,jdbcType=VARCHAR}
#{type9,jdbcType=VARCHAR}
#{type10,jdbcType=VARCHAR}
#{type11,jdbcType=VARCHAR}
#{type12,jdbcType=VARCHAR}
AND A.CCY = #{ccy,jdbcType=VARCHAR}
AND A.FINPROD_TYPE2 = #{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR} AND A.PROFIT_TYPE = #{PROFIT_TYPE_01, jdbcType = VARCHAR}
AND TO_CHAR(A.VDATE,'yyyy-MM-dd') > = #{startVDate}
AND TO_CHAR(A.VDATE,'yyyy-MM-dd') < = #{endVDate}
AND TO_CHAR(A.MDATE,'yyyy-MM-dd') > = #{startMDate}
AND TO_CHAR(A.MDATE,'yyyy-MM-dd') < = #{endMDate}
AND A.MANAGER = #{manager,jdbcType=VARCHAR}
AND A.ISSUER = #{issuer,jdbcType=VARCHAR}
AND A.TRUSTEE_ID = #{trusteeId,jdbcType=VARCHAR}
AND D.ACTUAL_MANAGER = #{actualManager,jdbcType=VARCHAR}
AND C.PUR_SPEED like concat(concat('%',#{purSpeed,jdbcType=VARCHAR}),'%')
AND C.RED_SPEED like concat(concat('%',#{redSpeed,jdbcType=VARCHAR}),'%')

SELECT COUNT(FINPROD_MARKET_ID) FROM FIN_PRODUCT LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
FIN_PRODUCT_TYPE.TYPE_8 IS NOT NULL
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}
